\section{Introduction}

\subsection{Motivation}
A recurring pattern in mathematical physics is the grading of a system by a discrete
quantum number: particle number, excitation level, defect count, lattice size. Symmetry
groups act at every level, and the natural object encoding all levels at once is a
generating function in a formal fugacity $q$ whose coefficients are level-by-level
counts. The analytic structure of such a generating function --- the location and order
of its singularities --- is the object of interest: poles at $q=1$ signal power-law
growth of the coefficients, higher-order poles signal higher-degree polynomial growth,
and non-rationality signals that no polynomial regime is ever reached.

In the situations we consider, the quantity counted at each level is not a number of
states but a number of \emph{symmetry classes}: we count $G$-orbits of ordered tuples of
distinct elements. This measurement is classical in permutation group theory, where
$r$-transitivity is the statement that the action on ordered $r$-tuples of distinct
points is transitive. What is new here is the graded, generating-function perspective:
we ask not whether a single action is $r$-transitive but how the deviation from
$r$-transitivity behaves as a function of the grading parameter, and what that behaviour
does to the analytic structure of the associated partition function.

\subsection{Summary of results}
Throughout, $G$ is a group and all generating functions are elements of the ring
$\ZZ[\![q]\!]$ of formal power series with integer coefficients, or, where
convergence is asserted, real-analytic functions on $|q|<1$. The main results are: the
Transitivity Criterion (Theorem~\ref{thm:crit}); the Difference Identity and the
Coefficient Formula (Theorems~\ref{thm:diffid},~\ref{thm:coeff}); the Exact Criterion
(Theorem~\ref{thm:exact}); the Polynomial Coefficient Theorem and its quantitative form
(Theorems~\ref{thm:polycoeff},~\ref{thm:quant}); the Main Rationality Theorem and its
analytic form (Theorems~\ref{thm:main},~\ref{thm:analytic}); the Descent Theorem and the
total partition function (Theorems~\ref{thm:descent},~\ref{thm:total}); the Burnside form
(Theorems~\ref{thm:burnside}--\ref{thm:fixgf}); sharpness of the exponent
(Theorems~\ref{thm:model}--\ref{thm:disjoint}); and an intermediate family
(Theorems~\ref{thm:cyc1}--\ref{thm:cyc3}).

\section{Definitions}

\begin{definition}[Graded $G$-set]
Let $G$ be a group. A \emph{graded $G$-set} is a family $(Y_n)_{n\ge 0}$ of sets, each
equipped with an action of $G$. We write $Y=\bigsqcup_{n\ge 0}Y_n$ and call $Y_n$ the
\emph{grade $n$}. No compatibility between different grades is assumed: the grading is
purely a bookkeeping index, exactly as a particle-number sector is in a Fock space
decomposition.
\end{definition}

\begin{definition}[Injective tuples]\label{def:inj}
For $r\ge 0$ and a set $Y$, an \emph{injective $r$-tuple} is an injective function
$f:\{1,\dots,r\}\to Y$; equivalently, an ordered list of $r$ pairwise distinct elements.
Write $\Inj_r(Y)$ for the set of these. If $G$ acts on $Y$ then $G$ acts on $\Inj_r(Y)$
by $(g\cdot f)(i)=g\cdot f(i)$; this is well defined since $y\mapsto g\cdot y$ is a
bijection with inverse $y\mapsto g^{-1}\cdot y$ and hence preserves injectivity. The set
$\Inj_r(Y)$ is canonically identified with the set of embeddings
$\{1,\dots,r\}\hookrightarrow Y$; for finite $Y$,
\[
|\Inj_r(Y)| \;=\; |Y|^{\underline r} \;=\; |Y|(|Y|-1)\cdots(|Y|-r+1),
\]
the descending factorial (equal to $0$ if $r>|Y|$ and to $1$ if $r=0$).
\end{definition}

\begin{definition}[Transitivity count]
For a $G$-set $Y$ and $r\ge 0$, the \emph{$r$-th transitivity count} is
$t_r(Y)=\#\big(\Inj_r(Y)/G\big)$, the number of $G$-orbits on injective $r$-tuples.
\end{definition}

\begin{definition}[$r$-transitivity]
$G$ acts \emph{$r$-transitively} on $Y$ if (i) $\Inj_r(Y)\ne\emptyset$, and (ii) for all
$a,b\in\Inj_r(Y)$ there is $g\in G$ with $g\cdot a=b$.
\end{definition}

\begin{definition}[Eventual $r$-transitivity]
A graded $G$-set $(Y_n)$ is \emph{eventually $r$-transitive} if there is $N$ such that
$G$ acts $r$-transitively on $Y_n$ for all $n\ge N$. The least such $N$ is the
\emph{onset index}.
\end{definition}

\begin{definition}[Transitivity partition function]
For a graded $G$-set with finite transitivity counts, set
$Z_r(q)=\sum_{n\ge 0}t_r(Y_n)q^n\in\ZZ[\![q]\!]$.
\end{definition}

\begin{definition}[Forward difference]
For $a:\NN\to\ZZ$ put $(\Delta a)_n=a_{n+1}-a_n$, and let $\Delta^s$ be the $s$-fold
iterate with $\Delta^0a=a$. Explicitly
$(\Delta^s a)_n=\sum_{k=0}^{s}(-1)^{s-k}\binom{s}{k}a_{n+k}$, so $(\Delta^s a)_n$ depends
only on $a_n,\dots,a_{n+s}$.
\end{definition}

\begin{definition}[Polynomiality of a series]
A formal power series $F\in\ZZ[\![q]\!]$ \emph{is a polynomial} if it lies
in the image of $\ZZ[q]\hookrightarrow\ZZ[\![q]\!]$; equivalently, if its
coefficients vanish from some index on. We say a series $A$ has \emph{denominator
dividing $(1-q)^s$} when $(1-q)^sA$ is a polynomial.
\end{definition}

\section{Transitivity counts as an order parameter}

\begin{theorem}[Growth Bound]\label{thm:growth}
Let $Y$ be a finite $G$-set and $r\ge 0$. Then $t_r(Y)\le |Y|^{\underline r}$.
\end{theorem}

\begin{proof}[Proof sketch]
The quotient map $\Inj_r(Y)\to\Inj_r(Y)/G$ is surjective, so the target has cardinality
at most that of the source, which is $|Y|^{\underline r}$ by Definition~\ref{def:inj}.
\end{proof}

\begin{theorem}[Transitivity Criterion]\label{thm:crit}
Let $G$ act on a set $Y$ and let $r\ge 0$. Then $t_r(Y)=1$ if and only if $G$ acts
$r$-transitively on $Y$.
\end{theorem}

\begin{proof}[Proof sketch]
A quotient set has exactly one element iff it is nonempty and any two of its elements
coincide. Nonemptiness of $\Inj_r(Y)/G$ is nonemptiness of $\Inj_r(Y)$, condition~(i).
Given that, all classes coincide iff for all $a,b$ there is $g$ with $g\cdot a=b$, using
symmetry of the orbit relation via $g^{-1}$; this is condition~(ii).
\end{proof}

Theorems~\ref{thm:growth} and~\ref{thm:crit} place $t_r(Y_n)$ between $1$ (maximal
symmetry) and $|Y_n|^{\underline r}$ (no symmetry, see \S\ref{sec:sharp}).

\section{The finite-difference core}

This section is independent of group theory. Write $A(q)=\sum_{n\ge 0}a_nq^n$ for the
generating function of $a:\NN\to\ZZ$.

\begin{lemma}\label{lem:polyiff}
A formal power series is a polynomial iff its coefficients vanish from some index on; if
they vanish above $M$, the polynomial has degree at most $M$.
\end{lemma}

\begin{theorem}[Difference Identity]\label{thm:diffid}
For any $a:\NN\to\ZZ$,
\[
(1-q)A(q) \;=\; a_0 \;+\; q\sum_{n\ge 0}(\Delta a)_nq^n .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Compare coefficients. In degree $0$ both sides give $a_0$. In degree $m+1$ the left side
gives $a_{m+1}-a_m$ and the right side gives $(\Delta a)_m=a_{m+1}-a_m$.
\end{proof}

Multiplication by $1-q$ is thus differencing, up to a shift and a constant term.

\begin{lemma}\label{lem:degpow}
$(1-q)^s$ is a polynomial of degree $s$; its coefficient in degree $m$ vanishes for
$m>s$.
\end{lemma}

\begin{theorem}[Coefficient Formula]\label{thm:coeff}
For all $s,n\ge 0$,
\[
\big[q^{\,n+s}\big]\Big((1-q)^sA(q)\Big) \;=\; (\Delta^s a)_n .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $s$; the case $s=0$ is the definition. For the step, Theorem~\ref{thm:diffid}
gives
\[
(1-q)^{s+1}A(q)=a_0(1-q)^s+q\Big((1-q)^s\textstyle\sum_n(\Delta a)_nq^n\Big).
\]
Extract the coefficient in degree $n+s+1$: the first summand contributes
$a_0\,[q^{n+s+1}](1-q)^s=0$ by Lemma~\ref{lem:degpow}, and the second contributes, after
removing the factor $q$, the coefficient of $q^{n+s}$ in
$(1-q)^s\sum_n(\Delta a)_nq^n$, which by induction is
$(\Delta^s(\Delta a))_n=(\Delta^{s+1}a)_n$.
\end{proof}

\begin{theorem}[Sufficiency]\label{thm:suff}
If $(\Delta^s a)_n=0$ for all $n\ge N$, then $(1-q)^sA(q)$ is a polynomial, of degree at
most $N+s-1$ when $s\ge 1$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:coeff} the coefficient of $q^m$ in $(1-q)^sA(q)$ equals
$(\Delta^s a)_{m-s}$ for $m\ge s$, hence vanishes for $m\ge N+s$; apply
Lemma~\ref{lem:polyiff}.
\end{proof}

\begin{theorem}[Necessity]\label{thm:nec}
If $(1-q)^sA(q)$ is a polynomial then there is $N$ with $(\Delta^s a)_n=0$ for all
$n\ge N$.
\end{theorem}

\begin{proof}[Proof sketch]
The coefficients of $(1-q)^sA(q)$ vanish above some $M$ by Lemma~\ref{lem:polyiff}; by
Theorem~\ref{thm:coeff}, $(\Delta^s a)_n$ is the coefficient in degree $n+s$, which
vanishes for $n\ge\max(M+1-s,0)$.
\end{proof}

\begin{theorem}[Exact Criterion]\label{thm:exact}
For every $s\ge 0$ and every $a:\NN\to\ZZ$, the series $(1-q)^sA(q)$ is a polynomial if
and only if there is $N$ with $(\Delta^s a)_n=0$ for all $n\ge N$.
\end{theorem}

Because this is a genuine equivalence, showing that a denominator cannot be lowered
requires only exhibiting a single nonvanishing entry in a difference column.

\begin{theorem}[Polynomial Coefficient Theorem]\label{thm:polycoeff}
Suppose there are $N\ge 0$, $r\ge 0$ and $P\in\ZZ[x]$ with $\deg P\le r$ such that
$a_n=P(n)$ for all $n\ge N$. Then $(1-q)^{r+1}A(q)$ is a polynomial.
\end{theorem}

\begin{proof}[Proof sketch]
Fix $n\ge N$. Since $(\Delta^{r+1}a)_n$ depends only on $a_n,\dots,a_{n+r+1}$, all equal
to the corresponding values of $P$, we may replace $a$ by $n\mapsto P(n)$. The forward
difference lowers the degree of a nonconstant polynomial by one and annihilates
constants, so $\Delta^{r+1}$ annihilates every polynomial of degree $\le r$; hence
$(\Delta^{r+1}a)_n=0$. Apply Theorem~\ref{thm:suff}.
\end{proof}

\begin{theorem}[Quantitative form]\label{thm:quant}
Under the hypotheses of Theorem~\ref{thm:polycoeff} there is $Q\in\ZZ[q]$ with
$\deg Q\le N+r$ and $A(q)=Q(q)/(1-q)^{r+1}$.
\end{theorem}

\begin{proof}[Proof sketch]
For $m>N+r$ write $m=k+(r+1)$ with $k\ge N$. By Theorem~\ref{thm:coeff} the coefficient
of $q^m$ in $(1-q)^{r+1}A(q)$ is $(\Delta^{r+1}a)_k=0$; apply Lemma~\ref{lem:polyiff}.
\end{proof}

\begin{corollary}[Eventually constant coefficients]\label{cor:const}
If $a_n=c$ for all $n\ge N$, then $(1-q)A(q)$ is a polynomial, hence so is
$(1-q)^{r+1}A(q)$ for every $r\ge 0$.
\end{corollary}

\section{The main theorem}

\begin{theorem}[Rationality of the transitivity partition function]\label{thm:main}
Let $(Y_n)$ be a graded $G$-set which is eventually $r$-transitive from index $N$ on.
Then $(1-q)^{r+1}Z_r(q)$ is a polynomial in $\ZZ[q]$: the series $Z_r$ is a rational
function of $q$ with denominator dividing $(1-q)^{r+1}$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:crit}, $t_r(Y_n)=1$ for all $n\ge N$, so the coefficient sequence is
eventually constant; apply Corollary~\ref{cor:const}.
\end{proof}

\begin{theorem}[Quantitative form]\label{thm:mainquant}
Under the hypotheses of Theorem~\ref{thm:main} there is $Q\in\ZZ[q]$ with
$\deg Q\le N+r$ and $Z_r(q)=Q(q)/(1-q)^{r+1}$.
\end{theorem}

\begin{remark}
The exponent $r+1$ is not optimal for this hypothesis alone --- eventual
$r$-transitivity already yields denominator $(1-q)$ --- but it is the correct ambient
exponent for the class of graded $G$-sets whose transitivity counts grow polynomially of
degree $r$, and \S\ref{sec:sharp} shows it is attained.
\end{remark}

\begin{lemma}[Eventually constant summation]\label{lem:sum}
Let $a:\NN\to\ZZ$ satisfy $a_n=c$ for all $n\ge N$, and let $q\in\mathbb{R}$ with
$|q|<1$. Then $\sum_na_nq^n$ converges absolutely and
\[
\sum_{n\ge 0}a_nq^n \;=\; \sum_{n<N}a_nq^n \;+\; \frac{c\,q^N}{1-q}.
\]
\end{lemma}

\begin{proof}[Proof sketch]
The shifted tail satisfies $a_{n+N}q^{n+N}=(c\,q^N)q^n$, a geometric series with ratio
$q$, hence summable with sum $cq^N/(1-q)$. Summability of the shifted tail gives
summability of the whole series, and splitting off the first $N$ terms gives the
identity.
\end{proof}

\begin{theorem}[Analytic form]\label{thm:analytic}
Let $(Y_n)$ be eventually $r$-transitive from index $N$, and let $q\in\mathbb{R}$ with
$|q|<1$. Then $Z_r(q)$ converges absolutely and
\[
Z_r(q) \;=\; \sum_{n<N}t_r(Y_n)q^n \;+\; \frac{q^N}{1-q}.
\]
Consequently $Z_r$ extends to a meromorphic function whose only singularity is a simple
pole at $q=1$ with residue $-1$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:crit} the coefficients equal $1$ from index $N$ on; apply
Lemma~\ref{lem:sum} with $c=1$.
\end{proof}

\begin{theorem}[Cleared denominator]\label{thm:cleared}
Under the same hypotheses, for $|q|<1$,
\[
(1-q)Z_r(q) \;=\; (1-q)\sum_{n<N}t_r(Y_n)q^n \;+\; q^N,
\]
a polynomial expression in $q$ of degree at most $N$.
\end{theorem}

Theorem~\ref{thm:analytic} exhibits the partition function as a \emph{transient plus a
bulk}: the pre-onset grades contribute a polynomial of degree $<N$, and the symmetric
regime contributes exactly the geometric tail $q^N/(1-q)$. The system has a single
critical fugacity $q=1$ and the transition there is of the mildest possible type.

\section{Descent and the total partition function}

\begin{theorem}[Descent]\label{thm:descent}
Let $Y$ be a finite $G$-set and $k\le r$. If $G$ acts $r$-transitively on $Y$, then $G$
acts $k$-transitively on $Y$.
\end{theorem}

\begin{proof}[Proof sketch]
Write $r=k+m$. Since $\Inj_{k+m}(Y)\ne\emptyset$ we have $|Y|\ge k+m$. Given injective
$k$-tuples $a,b$, extend each to an injective $(k+m)$-tuple by appending $m$ further
elements from the complement of the image, which has at least $m$ elements. Call the
extensions $A,B$; by $r$-transitivity there is $g$ with $g\cdot A=B$, and restricting to
the first $k$ coordinates gives $g\cdot a=b$. Nonemptiness of $\Inj_k(Y)$ follows by
restriction.
\end{proof}

\begin{corollary}\label{cor:desc}
If a graded $G$-set with finite grades is eventually $r$-transitive from index $N$, then
$t_k(Y_n)=1$ for all $n\ge N$ and all $k\le r$.
\end{corollary}

\begin{theorem}[Total transitivity partition function]\label{thm:total}
Under the hypotheses of Corollary~\ref{cor:desc}, the series
$Z^{\mathrm{tot}}_r(q)=\sum_{n\ge 0}\big(\sum_{k=0}^{r}t_k(Y_n)\big)q^n$ is rational with
denominator dividing $(1-q)^{r+1}$.
\end{theorem}

\begin{proof}[Proof sketch]
For $n\ge N$ the inner sum equals $r+1$; apply Corollary~\ref{cor:const} with $c=r+1$.
\end{proof}

\section{The fixed-point (Burnside) form}

For $g\in G$ let $\Fix_r(g,Y)=\{f\in\Inj_r(Y):g\cdot f=f\}$.

\begin{theorem}[Burnside's lemma for injective tuples]\label{thm:burnside}
Let $G$ be a finite group acting on a finite set $Y$ and let $r\ge 0$. Then
\[
\sum_{g\in G}\big|\Fix_r(g,Y)\big| \;=\; t_r(Y)\cdot|G| .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Apply the orbit-counting lemma to the finite $G$-set $\Inj_r(Y)$: the number of orbits is
the average number of fixed points. Multiply by $|G|$.
\end{proof}

\begin{theorem}[Degeneracy at transitivity]\label{thm:degen}
If $G$ is finite and acts $r$-transitively on the finite set $Y$, then
$\sum_{g\in G}|\Fix_r(g,Y)|=|G|$: the average number of fixed injective $r$-tuples per
group element is exactly $1$.
\end{theorem}

\begin{theorem}[Fixed-point partition function]\label{thm:fixgf}
Let $G$ be finite and let $(Y_n)$ be a graded $G$-set with finite grades, eventually
$r$-transitive from index $N$. Then
$F_r(q)=\sum_{n\ge 0}\big(\sum_{g\in G}|\Fix_r(g,Y_n)|\big)q^n$ is rational with
denominator dividing $(1-q)^{r+1}$, its coefficients being eventually the constant
$|G|$; for $|q|<1$,
\[
F_r(q) \;=\; \sum_{n<N}\Big(\sum_{g\in G}|\Fix_r(g,Y_n)|\Big)q^n \;+\;
\frac{|G|\,q^N}{1-q}.
\]
\end{theorem}

\begin{corollary}[Explicit coefficients]\label{cor:explicit}
For finite $G$ and finite $Y$,
\[
t_r(Y) \;=\; \frac{1}{|G|}\sum_{g\in G}|Y^g|^{\underline r},
\qquad Y^g=\{y\in Y: g\cdot y=y\}.
\]
\end{corollary}

\begin{proof}[Proof sketch]
An injective $r$-tuple is fixed by $g$ iff each entry is, so the fixed tuples are exactly
the injective $r$-tuples in $Y^g$, of which there are $|Y^g|^{\underline r}$. Substitute
into Theorem~\ref{thm:burnside}.
\end{proof}

\section{Sharpness: the exponent \texorpdfstring{$r+1$}{r+1} is attained}
\label{sec:sharp}

\begin{theorem}[The extremal model]\label{thm:model}
For every $r\ge 0$,
\[
(1-q)^{r+1}\sum_{n\ge 0}\binom{n+r}{r}q^n=1,
\qquad\text{i.e.}\qquad
\sum_{n\ge 0}\binom{n+r}{r}q^n=\frac{1}{(1-q)^{r+1}} .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $r$. For $r=0$ the sequence is constant $1$ and $(1-q)\sum q^n=1$ by
telescoping. For the step, Pascal's rule
$\binom{n+1+(r+1)}{r+1}=\binom{n+(r+1)}{r+1}+\binom{n+(r+1)}{r}$ says exactly that
multiplying the $(r+1)$-series by $(1-q)$ yields the $r$-series.
\end{proof}

\begin{theorem}[Optimality of the exponent]\label{thm:opt}
For every $s\le r$, the series $(1-q)^s\sum_n\binom{n+r}{r}q^n$ is not a polynomial.
\end{theorem}

\begin{proof}[Proof sketch]
Iterating the step of Theorem~\ref{thm:model} gives
$(1-q)^r\sum_n\binom{n+r}{r}q^n=\sum_nq^n$, the all-ones series, which is not a
polynomial. If $(1-q)^s\sum_n\binom{n+r}{r}q^n$ were a polynomial for some $s\le r$,
multiplying by $(1-q)^{r-s}$ would make the all-ones series a polynomial.
\end{proof}

\begin{theorem}[Transitivity counts of a trivial action]\label{thm:triv}
If $G$ acts trivially on a finite set $Y$ then $t_r(Y)=|Y|^{\underline r}$. In particular
for the family $Y_n$ of $n$ labelled points with trivial action,
$t_r(Y_n)=n^{\underline r}=n(n-1)\cdots(n-r+1)$, a polynomial in $n$ of degree exactly
$r$.
\end{theorem}

\begin{proof}[Proof sketch]
The induced action on injective tuples is trivial, so orbits are singletons and the
number of orbits equals $|\Inj_r(Y)|=|Y|^{\underline r}$.
\end{proof}

\begin{theorem}[Exact denominator]\label{thm:exactden}
For the trivial-action family, $(1-q)^{r+1}\sum_nt_r(Y_n)q^n$ is a polynomial, while for
every $s\le r$ the series $(1-q)^s\sum_nt_r(Y_n)q^n$ is not. The denominator is exactly
$(1-q)^{r+1}$.
\end{theorem}

\begin{proof}[Proof sketch]
Polynomiality follows from Theorem~\ref{thm:polycoeff} applied to the degree-$r$
polynomial $x(x-1)\cdots(x-r+1)$. Conversely the $r$-th difference of
$n\mapsto n^{\underline r}$ is the constant $r!$, which never vanishes, so by
Theorem~\ref{thm:exact} the exponent $r$ fails; multiplying by $(1-q)^{r-s}$ propagates
the failure to every $s\le r$.
\end{proof}

\begin{theorem}[Disjointness of the regimes]\label{thm:disjoint}
For $r\ge 1$ the trivial-action family is never eventually $r$-transitive.
\end{theorem}

\begin{proof}[Proof sketch]
Otherwise $n^{\underline r}=1$ for all large $n$; but for $r\ge 1$ and $n\ge r+2$,
$n^{\underline r}=(n-r+1)\,n^{\underline{r-1}}\ge 2$.
\end{proof}

\section{An intermediate family: translations of a cyclic grade}

Let $G=\ZZ$ act on the grade $Y_n=\ZZ/n\ZZ$ by translation, $k\cdot x=x+\bar k$.

\begin{theorem}[Every grade is $1$-transitive]\label{thm:cyc1}
For every $n\ge 1$, $\ZZ$ acts $1$-transitively on $\ZZ/n\ZZ$.
\end{theorem}

\begin{proof}[Proof sketch]
The grade is nonempty, and given $x,y$ any integer $k$ with $\bar k=y-x$ translates $x$
to $y$.
\end{proof}

\begin{theorem}[Second transitivity count]\label{thm:cyc2}
For $n\ge 1$, $t_2(\ZZ/n\ZZ)=n-1$.
\end{theorem}

\begin{proof}[Proof sketch]
Send an injective pair $(x,y)$ to $y-x$, a nonzero residue. Translation preserves the
difference, so this descends to orbits. It is injective: two pairs with the same
difference are related by the translation matching their first coordinates, which then
automatically matches their second coordinates. It is surjective: $(0,d)$ realises any
$d\ne 0$. Hence the orbits biject with the nonzero residues.
\end{proof}

\begin{theorem}[Exact denominator $(1-q)^2$]\label{thm:cyc3}
With $Y_n=\ZZ/(n+1)\ZZ$, so that $t_2(Y_n)=n$, the series $(1-q)^2\sum_nt_2(Y_n)q^n$ is a
polynomial (indeed equal to $q$), while $(1-q)\sum_nt_2(Y_n)q^n$ is not.
\end{theorem}

\begin{proof}[Proof sketch]
The coefficient sequence is $a_n=n$, whose first difference is the constant $1$ (never
zero) and whose second difference vanishes identically; apply Theorem~\ref{thm:exact} in
both directions. Explicitly $\sum_nnq^n=q/(1-q)^2$.
\end{proof}

By Theorem~\ref{thm:exact} the order of the pole at $q=1$ is, in general, the least $s$
with $\Delta^st_r$ eventually zero, i.e.\ one more than the polynomial degree of the
eventual growth of the transitivity counts. The pole order is a symmetry-deficit
exponent.

\section{Algorithms}

\begin{algorithmbox}[Transitivity count by fixed points]
Given a finite group $G$ acting on a finite set $Y$ and an order $r$, compute
$t_r(Y)=\frac{1}{|G|}\sum_{g\in G}|Y^g|^{\underline r}$ (Corollary~\ref{cor:explicit}).
Cost: $O(|G|\cdot|Y|)$ operations to build all fixed sets plus $O(|G|\cdot r)$ to form
the descending factorials --- exponentially cheaper than orbit enumeration, which
requires a union--find over $|Y|^{\underline r}$ tuples.
\end{algorithmbox}

\begin{algorithmbox}[Denominator detection]
Given the first $M+1$ terms of a coefficient sequence, build the difference table
$\Delta^0a,\Delta^1a,\dots$ and report the least $s$ whose row vanishes on a stable
suffix. By Theorem~\ref{thm:exact} this $s$ is the order of the pole at $q=1$, and the
numerator is the truncation of $(1-q)^sA(q)$. Cost: $O(M^2)$ subtractions.
\end{algorithmbox}

\begin{algorithmbox}[Numerator extraction]
Given $a$ eventually equal to a polynomial of degree $\le r$ from index $N$, compute
$Q(q)=(1-q)^{r+1}A(q)$ by convolving the first $N+r+1$ coefficients of $a$ with the
binomial coefficients of $(1-q)^{r+1}$; Theorem~\ref{thm:quant} guarantees no further
terms are needed. Cost: $O((N+r)r)$.
\end{algorithmbox}

\section{Discussion}

\subsection{What the pole order measures}
The classical mantra ``rational generating function with denominator a power of $(1-q)$
if and only if quasi-polynomial coefficients'' is here made exact and constructive by the
Coefficient Formula. Because the criterion is a genuine equivalence, the analytic
invariant (order of the pole at $q=1$) and the combinatorial invariant (least vanishing
difference column) coincide on the nose, with an explicit index shift. For transitivity
counts this gives a symmetry-deficit exponent: pole order $1$ means eventual
$r$-transitivity; pole order $s$ means the number of orbit classes of $r$-tuples grows
like a polynomial of degree $s-1$ in the grading parameter.

\subsection{Physical reading}
Interpreting $q$ as a fugacity and $n$ as a sector index, $Z_r$ is the partition function
of a system whose sector weights are symmetry-class counts. Theorem~\ref{thm:analytic}
says the free energy has a logarithmic singularity at $q=1$ of the simplest kind whenever
the system is eventually symmetric; no exotic critical behaviour is possible. The
Burnside form is the ``sum over sectors of the gauge group'' version of the same
quantity, and Theorem~\ref{thm:degen} states complete degeneracy: in the symmetric phase
each group element contributes, on average, exactly one frozen configuration.

\subsection{Scope and limitations}
The results are stated for denominators that are powers of $(1-q)$; families with
quasi-polynomial counts require denominators $(1-q^p)^{d+1}$ and are not covered, though
the difference machinery adapts by using the operator $a_n\mapsto a_{n+p}-a_n$. The
descent theorem is stated for finite grades, its extension argument using a cardinality
count. The analytic form is stated for real $q\in(-1,1)$; the complex statement follows
by the same geometric-series argument.

\subsection{Relation to classical permutation group theory}
Multiply transitive groups are rare and classified: apart from symmetric and alternating
groups, only the Mathieu groups are $4$- or $5$-transitive. Our results are complementary
in orientation: rather than classifying actions with $t_r=1$, we study families in which
$t_r$ \emph{converges} to $1$ and quantify the rate through the analytic structure of a
generating function. The onset index $N$ and the numerator degree $N+r$ record how long
the family takes to become highly transitive.

\section{Future directions}

\begin{conjecture}[Quasi-polynomial dichotomy for graded $G$-sets of polynomial size]
Let $Y=\bigsqcup_nY_n$ be a graded $G$-set with $|Y_n|\le Cn^d$ for all $n$. Then either
$t_r(Y_n)$ is eventually quasi-polynomial in $n$ of degree $\le dr$ --- so
$\sum_nt_r(Y_n)q^n$ is rational with denominator dividing $(1-q^p)^{dr+1}$ for some
period $p$ --- or $t_r(Y_n)$ is unbounded along a sparse set of grades of density $0$.
The Growth Bound caps the growth by a degree-$dr$ polynomial, and by the Exact Criterion
rationality with that denominator is equivalent to eventual vanishing of the
$(dr+1)$-st difference, turning an analytic question into a combinatorial one about
difference tables.
\end{conjecture}

\begin{conjecture}[Sharp numerator degree equals the onset of transitivity]
If $N$ is the least index from which all grades are $r$-transitive and some grade below
$N$ is not, then the numerator $Q$ of $\sum_nt_r(Y_n)q^n=Q(q)/(1-q)^{r+1}$ has
$\deg Q=N+r$ exactly (not merely $\le$), and $Q(1)=1$. The bound $N+r$ is available from
the quantitative form, and the Coefficient Formula identifies the top coefficient of $Q$
with a single entry of the $(r+1)$-st difference table at the last irregular grade;
sharpness is thus a one-entry non-vanishing statement.
\end{conjecture}

\begin{conjecture}[Transitivity spectrum rigidity]
For a graded $G$-set with all grades finite, the transitivity spectrum
$k\mapsto(\text{least }N\text{ with all grades}\ge N\text{ being }k\text{-transitive})$ is
non-decreasing in $k$ and is either finite for all $k$ --- forcing $|G|$ to be infinite
or the grades to be eventually bounded --- or finite exactly on an initial segment
$k\le r_0$. The Descent Theorem makes $k$-transitivity monotone downward in $k$, so the
spectrum is an initial segment; what remains is to show that a uniform bound over all $k$
forces the structural dichotomy, via the Burnside identity.
\end{conjecture}

\begin{conjecture}[Fixed-point spectral gap]
For a finite group $G$ and a graded $G$-set eventually $r$-transitive from index $N$, the
sequence $n\mapsto\max_{g\ne 1}|\Fix_r(g,Y_n)|$ is eventually $0$: in the symmetric phase
only the identity contributes fixed injective $r$-tuples once $|Y_n|$ exceeds an explicit
bound depending on $|G|$ and $r$. This refines the Degeneracy Theorem from a statement
about the average to one about individual terms.
\end{conjecture}

\begin{conjecture}[Two-variable rationality]
The bivariate series $\sum_{n,k}t_k(Y_n)z^kq^n$ of an eventually $r$-transitive graded
$G$-set, truncated to $k\le r$, is rational in $(z,q)$ with denominator $(1-q)(1-z)$ up to
a polynomial correction supported on the pre-onset grades.
\end{conjecture}

\section{Conclusion}

The transitivity partition function of a graded $G$-set that eventually becomes
$r$-transitive is a rational function of the fugacity $q$ with denominator dividing
$(1-q)^{r+1}$ and numerator of degree at most $N+r$ determined by the transient
pre-onset grades; on the unit disc it equals a finite polynomial plus the geometric tail
$q^N/(1-q)$, exhibiting a single simple pole at $q=1$ and nothing else. The mechanism is
a two-way equivalence between powers of $(1-q)$ in the denominator and vanishing columns
of the difference table, made precise by the identity
$[q^{n+s}]\big((1-q)^sA(q)\big)=(\Delta^sa)_n$. This equivalence yields sharpness rather
than a mere bound: the exponent $r+1$ is attained by the trivial-action family, whose
counts are the descending factorials $n^{\underline r}$, and intermediate pole orders are
realised by families such as the integers translating cyclic grades. Burnside's lemma
recasts the coefficients as sums over the group of fixed-point counts, so the whole
partition function reads as a trace over the symmetry group, degenerating to the constant
$|G|$ exactly in the symmetric phase.

\end{document}

