"""Transitivity counts two ways: orbit enumeration versus the fixed-point formula.

For a finite group G acting on a finite set Y, the r-th transitivity count t_r(Y) is the
number of G-orbits on injective r-tuples (ordered lists of r distinct points).  It can be
computed either by explicitly merging tuples into orbits, or by the fixed-point average

        t_r(Y) = (1/|G|) * sum_{g in G} |Y^g|^{underline r},

since an injective r-tuple is fixed by g exactly when all of its entries lie in the fixed
set Y^g.  This script computes both for the trivial, cyclic, dihedral, affine and full
symmetric groups, checks that they agree, and flags the r-transitive cases (t_r = 1).
Only the standard library is used.
"""

from __future__ import annotations

from itertools import permutations
from math import gcd
from typing import Dict, List, Sequence, Set, Tuple

Perm = Tuple[int, ...]


def compose(p: Perm, q: Perm) -> Perm:
    return tuple(p[q[i]] for i in range(len(q)))


def closure(generators: Sequence[Perm], degree: int) -> List[Perm]:
    identity: Perm = tuple(range(degree))
    seen: Set[Perm] = {identity}
    frontier: List[Perm] = [identity]
    while frontier:
        nxt: List[Perm] = []
        for p in frontier:
            for g in generators:
                r = compose(g, p)
                if r not in seen:
                    seen.add(r)
                    nxt.append(r)
        frontier = nxt
    return sorted(seen)


def trivial_group(n: int) -> List[Perm]:
    return [tuple(range(n))]


def cyclic_group(n: int) -> List[Perm]:
    return closure([tuple((i + 1) % n for i in range(n))], n) if n else [()]


def dihedral_group(n: int) -> List[Perm]:
    if not n:
        return [()]
    shift = tuple((i + 1) % n for i in range(n))
    flip = tuple((-i) % n for i in range(n))
    return closure([shift, flip], n)


def affine_group(n: int) -> List[Perm]:
    """x -> a x + b on Z/nZ with a invertible; 2-transitive exactly when n is prime."""
    out: List[Perm] = []
    for a in range(1, max(n, 2)):
        if gcd(a, n) != 1:
            continue
        for b in range(n):
            out.append(tuple((a * i + b) % n for i in range(n)))
    return out or [tuple(range(n))]


def symmetric_group(n: int) -> List[Perm]:
    return [tuple(p) for p in permutations(range(n))]


def desc_factorial(m: int, r: int) -> int:
    if r > m:
        return 0
    out = 1
    for i in range(r):
        out *= m - i
    return out


def count_by_orbits(group: Sequence[Perm], degree: int, r: int) -> int:
    tuples: List[Tuple[int, ...]] = list(permutations(range(degree), r))
    index: Dict[Tuple[int, ...], int] = {t: i for i, t in enumerate(tuples)}
    parent: List[int] = list(range(len(tuples)))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for t in tuples:
        i, j = find(index[t]), None
        for g in group:
            j = find(index[tuple(g[x] for x in t)])
            if i != j:
                parent[i] = j
                i = j
    return len({find(i) for i in range(len(tuples))})


def count_by_fixed_points(group: Sequence[Perm], degree: int, r: int) -> int:
    total = sum(desc_factorial(sum(1 for i in range(degree) if g[i] == i), r)
                for g in group)
    assert total % len(group) == 0, "the Burnside average must be an integer"
    return total // len(group)


def main() -> None:
    header = f"{'group':>16} {'n':>3} {'r':>2} {'|G|':>6} {'orbits':>8} {'fixed pts':>10} {'t_r=1?':>7}"
    print(header)
    print("-" * len(header))
    for name, builder in (("trivial", trivial_group), ("cyclic", cyclic_group),
                          ("dihedral", dihedral_group), ("affine", affine_group),
                          ("symmetric", symmetric_group)):
        for n in (5, 6, 7):
            g = builder(n)
            for r in (1, 2, 3):
                a = count_by_orbits(g, n, r)
                b = count_by_fixed_points(g, n, r)
                assert a == b, (name, n, r, a, b)
                print(f"{name:>16} {n:>3} {r:>2} {len(g):>6} {a:>8} {b:>10} "
                      f"{('yes' if b == 1 else 'no'):>7}")
    print("\nThe affine group on Z/nZ is 2-transitive exactly for prime n (5, 7 here but")
    print("not 6); the cyclic and dihedral groups are only 1-transitive; the symmetric")
    print("group is r-transitive for every r <= n; the trivial group for r = 0 only.")


if __name__ == "__main__":
    main()

