"""Orbit-counting computation of the transitivity count t_r(Y) via fixed points."""

from __future__ import annotations

from typing import List, Sequence, Tuple

Perm = Tuple[int, ...]


def descending_factorial(m: int, r: int) -> int:
    """m^{underline r} = m (m-1) ... (m-r+1), and 0 when r > m."""
    if r > m:
        return 0
    out = 1
    for i in range(r):
        out *= m - i
    return out


def fixed_point_count(g: Perm) -> int:
    """|Y^g|, the number of points left in place by the permutation g."""
    return sum(1 for i, image in enumerate(g) if image == i)


def transitivity_count(group: Sequence[Perm], degree: int, r: int) -> int:
    """t_r(Y) = (1/|G|) sum_{g in G} |Y^g|^{underline r}.

    Y = {0, ..., degree-1}; `group` is the full list of permutations of G.
    Runs in O(|G| * (degree + r)) integer operations and O(1) extra memory.
    """
    if not group:
        raise ValueError("the group must contain at least the identity")
    total = 0
    for g in group:
        total += descending_factorial(fixed_point_count(g), r)
    if total % len(group) != 0:
        raise ArithmeticError("Burnside average is not an integer: bad group data")
    return total // len(group)


def is_transitive_of_degree(group: Sequence[Perm], degree: int, r: int) -> bool:
    """G acts r-transitively on Y exactly when t_r(Y) = 1."""
    if descending_factorial(degree, r) == 0:
        return False
    return transitivity_count(group, degree, r) == 1


def graded_transitivity_counts(groups: Sequence[Sequence[Perm]], degrees: Sequence[int],
                               r: int) -> List[int]:
    """The coefficient sequence t_r(Y_0), t_r(Y_1), ... of a graded G-set."""
    return [transitivity_count(g, d, r) for g, d in zip(groups, degrees)]
